#!/usr/bin/env bash
# Local OIDC test environment: Authelia (file users) + Caddy (local TLS) in
# Docker, in front of a birdcam-server running on this host on :8080.
#
#   dev/up.sh        generate secrets/configs (once) and start the containers
#   dev/down.sh      stop the containers
#
# Generated files (secrets!) live in dev/.secrets/ which is git-ignored.
# URLs (*.localhost resolves to loopback on modern systems/browsers):
#   https://birdcam.localhost:8443        birdcam (proxied to host :8080)
#   https://auth.birdcam.localhost:8443   Authelia
set -euo pipefail

AUTHELIA_IMAGE=authelia/authelia:4.39.28
DEV=$(cd "$(dirname "$0")" && pwd)
SEC=$DEV/.secrets
mkdir -p "$SEC/authelia" "$SEC/caddy-data" "$SEC/state"
chmod 700 "$SEC"

rand() { openssl rand -hex 32; }
authelia() { docker run --rm "$AUTHELIA_IMAGE" authelia "$@"; }
digest() { authelia crypto hash generate "$@" | sed -n 's/^Digest: //p'; }

if [ ! -f "$SEC/generated" ]; then
	echo "Generating secrets (first run)..."
	rand >"$SEC/jwt-secret"
	rand >"$SEC/session-secret"
	rand >"$SEC/storage-key"
	rand >"$SEC/hmac-secret"
	rand >"$SEC/client-secret"
	rand >"$SEC/birdcam-session.key"
	openssl rand -hex 24 >"$SEC/device-key"
	openssl genrsa -out "$SEC/oidc.key" 2048 2>/dev/null
	digest pbkdf2 --variant sha512 --password "$(cat "$SEC/client-secret")" >"$SEC/client-secret.hash"
	digest argon2 --password alice >"$SEC/alice.hash"
	digest argon2 --password bob >"$SEC/bob.hash"
	touch "$SEC/generated"
fi

cat >"$SEC/authelia/users.yml" <<EOF
# Dev users. Passwords: alice/alice, bob/bob.
users:
  alice:
    displayname: Alice
    email: alice@example.com
    password: '$(cat "$SEC/alice.hash")'
    groups: [family]
  bob:
    displayname: Bob
    email: bob@example.com
    password: '$(cat "$SEC/bob.hash")'
    groups: []
EOF

cat >"$SEC/authelia/configuration.yml" <<EOF
server:
  address: 'tcp://:9091'
log:
  level: info
theme: dark
ntp:
  disable_startup_check: true
identity_validation:
  reset_password:
    jwt_secret: '$(cat "$SEC/jwt-secret")'
authentication_backend:
  file:
    path: /config/users.yml
access_control:
  default_policy: one_factor
session:
  secret: '$(cat "$SEC/session-secret")'
  cookies:
    - domain: 'birdcam.localhost'
      authelia_url: 'https://auth.birdcam.localhost:8443'
storage:
  encryption_key: '$(cat "$SEC/storage-key")'
  local:
    path: /config/db.sqlite3
notifier:
  filesystem:
    filename: /config/notification.txt
identity_providers:
  oidc:
    hmac_secret: '$(cat "$SEC/hmac-secret")'
    jwks:
      - key_id: main
        algorithm: RS256
        use: sig
        key: |
$(sed 's/^/          /' "$SEC/oidc.key")
    clients:
      - client_id: birdcam
        client_name: BirdCam (dev)
        client_secret: '$(cat "$SEC/client-secret.hash")'
        public: false
        authorization_policy: one_factor
        require_pkce: true
        pkce_challenge_method: S256
        redirect_uris:
          - https://birdcam.localhost:8443/auth/callback
        scopes: [openid, profile, email, groups]
        response_types: [code]
        grant_types: [authorization_code]
        token_endpoint_auth_method: client_secret_basic
EOF

# birdcam-server config for this environment.
cat >"$SEC/server.yaml" <<EOF
# Generated by dev/up.sh. Run: SSL_CERT_FILE=$SEC/caddy-root.crt bin/birdcam-server -config $SEC/server.yaml
listen: ":8080"
external_url: https://birdcam.localhost:8443
state_dir: $SEC/state
auth:
  oidc:
    issuer: https://auth.birdcam.localhost:8443
    client_id: birdcam
    client_secret_file: $SEC/client-secret
  session_key_file: $SEC/birdcam-session.key
hosts:
  - host: birdcam.localhost
    default_device: test-pi
ingest:
  port_min: 9001
  port_max: 9010
  tls: true
webrtc:
  udp_port: 8189
default_profile: {width: 1280, height: 720, fps: 30, audio: true}
devices:
  - id: test-pi
    key: "$(cat "$SEC/device-key")"
    name: Test Pi
cameras:
  # The test rig's cameras: one private (group family), the others public.
  - device_id: test-pi
    camera_id: usb-usb-camera-manufacture-h264-usb-camera-2020052801
    name: H.264 camera (family only)
    groups: [family]
  - device_id: test-pi
    camera_id: usb-generic-general-uvc
    name: C1 lookalike
  - device_id: test-pi
    camera_id: usb-microsoft-microsoft-lifecam-studio-tm
    name: LifeCam
EOF

docker compose -f "$DEV/compose.yaml" up -d

# Caddy creates its local CA on first start; the server needs it to reach Authelia.
for _ in $(seq 1 30); do
	if docker compose -f "$DEV/compose.yaml" exec -T caddy cat /data/caddy/pki/authorities/local/root.crt >"$SEC/caddy-root.crt" 2>/dev/null && [ -s "$SEC/caddy-root.crt" ]; then
		break
	fi
	sleep 1
done

cat <<EOF

Up. Next:
  1. Start the server:  SSL_CERT_FILE=$SEC/caddy-root.crt bin/birdcam-server -config $SEC/server.yaml
  2. Agent config on the Pi: device_id: test-pi, key: $(cat "$SEC/device-key")
  3. Trust the local CA in your browser, or accept the warning once per host:
       $SEC/caddy-root.crt
  4. Open https://birdcam.localhost:8443  (users: alice/alice in group family, bob/bob no groups)
EOF
